// Offline product interaction only. All actors, evidence and receipts below are fixtures.
function controlSeed(){return {
 boundary:{id:'X1',revision:1,state:'draft',goal:'指定公司与财年，从正确原件导出 CSV 和出处。',excluded:'不增加跨年份对比，不新增业务调用，不部署或正式采纳。',source:null},
 organization:{mode:'parallel',revision:1,predecessor:201,successor:70,milestone:'兼容接口已合入且消费者证据适用',handoff:'not-requested'},
 stopNew:false,stopMerge:false,stoppedBatches:[],controlRevision:1,decisions:[],outcomes:[],drift:[],lastAccepted:'尚无本轮已接受成果',lastAction:null
};}
function controlRecord(kind,text,origin,authority,refs={}){const c=s.control,op=operation('project-control',kind,text);finish(op,text+'（离线演练）');const item={id:'D-'+op.id,kind,text,origin,authority,at:time(),revision:c.controlRevision,...refs};c.decisions.unshift(item);c.lastAction=item;event('项目控制 · '+kind,text,{operation:op.id});return item;}
function controlOwner(action,payload={},actor='owner-ui'){const c=s.control;if(actor!=='owner-ui'||s.mode==='readonly')return {ok:false,reason:'需要本人控制入口；模型转述与只读模式不能改变控制。'};const note=String(payload.note||'').trim();if(!note)return {ok:false,reason:'需要本次具体安排与作用范围。'};if(!['adopt','organization','stop-new','resume-new','revoke-merge','restore-merge','stop-batch','resume-batch'].includes(action))return {ok:false,reason:'未支持的控制动作。'};if(action==='adopt'&&payload.revision!==c.boundary.revision)return {ok:false,reason:'目标版本已变化，请重读。'};if(action==='organization'&&!['parallel','serial','unified'].includes(payload.mode))return {ok:false,reason:'未知组织方式。'};c.controlRevision++;
 if(action==='adopt'){if(payload.revision!==c.boundary.revision)return {ok:false,reason:'目标版本已变化，请重读。'};c.boundary.state='adopted';c.boundary.source='本人入口／本轮确认（模拟）';}
 else if(action==='organization'){if(!['parallel','serial','unified'].includes(payload.mode))return {ok:false,reason:'未知组织方式。'};c.organization={...c.organization,mode:payload.mode,revision:c.organization.revision+1,handoff:payload.mode==='unified'?'pending':'not-requested'};}
 else if(action==='stop-new'){c.stopNew=true;s.coord.newWorkPaused=true;}
 else if(action==='resume-new'){c.stopNew=false;s.coord.newWorkPaused=false;}
 else if(action==='revoke-merge'){c.stopMerge=true;s.grantActive=false;}
 else if(action==='restore-merge'){c.stopMerge=false;s.grantActive=true;}
 else if(action==='stop-batch'){if(!c.stoppedBatches.includes('X1'))c.stoppedBatches.push('X1');}
 else if(action==='resume-batch'){c.stoppedBatches=c.stoppedBatches.filter(x=>x!=='X1');}
 else return {ok:false,reason:'未支持的控制动作。'};
 const item=controlRecord(action,note,'本人明确决定（模拟）','本人入口；不代表真实授权',{source:'owner-ui',scope:'当前项目／'+(action.includes('batch')?'X1':action.includes('merge')?'新合并请求':action==='organization'?'B 的共享实施':'已说明范围')});return {ok:true,item};}
function controlGate(task,phase='implementation'){const c=s.control;if(s.mode==='readonly')return {ok:false,reason:'只读模式'};if(phase==='investigation')return {ok:true,reason:'已获准的只读调查可继续'};if(c.stopNew||s.coord.newWorkPaused)return {ok:false,reason:'已停止新增实施；现有运行需核查，不强杀'};if(+task===70){if(c.stoppedBatches.includes('X1'))return {ok:false,reason:'X1 已停止新增投入'};if(c.boundary.state!=='adopted')return {ok:false,reason:'等待本人采用本批目标，不是等待技术评论'};if(c.organization.mode==='unified'&&c.organization.handoff!=='confirmed')return {ok:false,reason:'统一负责人尚待原写入者安全交接'};if(c.organization.mode==='serial'&&!depOK({type:'pr',id:c.organization.predecessor,target:'main'}))return {ok:false,reason:'B 的共享实施等 A1 及有效证据，不等整个 Issue A'};}return {ok:true,reason:'仍须通过任务范围、技术协调和工作区检查'};}
function controlHandoff(proof){const c=s.control,t=T(70),old=t?.owner?S(t.owner):null;if(s.mode==='readonly'||c.organization.mode!=='unified'||!s.coord.intake?.approved||!t||!proof||old&&['running','unknown','starting','pausing','waiting'].includes(old.state)||s.ops.some(o=>['pending','running','sent','unknown'].includes(o.state)&&String(o.target)==='70'))return false;if(old){old.tasks=old.tasks.filter(x=>x!==70);t.owner=null;}c.organization.handoff='confirmed';controlRecord('handoff','原写入责任已核对，下一次派发只加入 A 的待办（演练）','团队技术约定（模拟）','既有分工范围内；'+proof);return true;}
function controlTechnical(note,actor='receiver'){if(!['issue_owner','receiver'].includes(actor)||s.mode==='readonly')return false;const c=s.control;if(c.boundary.state!=='adopted')return false;controlRecord('technical-plan',note,'团队技术约定（模拟）','本批目标内的接收／实现委托',{boundaryRevision:c.boundary.revision,planRevision:s.coord.intake?.revision||1});return true;}
function controlOutcome(record){const c=s.control;if(!record.id||!record.candidate||!record.judgment||!record.evidence||!record.taskClass||!record.modelVersion||!record.promptVersion||!record.observedAt||!['escaped','refuted','unnecessary-escalation','no-incident-observed','unknown','changed-goal'].includes(record.result))return false;if(c.outcomes.some(x=>x.id===record.id))return false;c.outcomes.push({...record});return true;}
function controlModal(kind){const c=s.control;let title='项目控制',body='',options='';
 if(kind==='boundary'){title='采用本批目标';body=`<div class="control-adoption"><b>本人保留的边界 · ${esc(c.boundary.id)} v${c.boundary.revision}</b><p>${esc(c.boundary.goal)}</p><p>不做：${esc(c.boundary.excluded)}</p><small>技术拆分和内部子 Issue 不逐项重批；改变成果、费用或可接受失败才回到这里。</small></div>`;options='<input type="hidden" id="control-choice" value="adopt">';}
 else if(kind==='organization'){title='选择组织方式，而不是增加协调层';body='<p class="small sub">本例仅改变 B 的共享实施。只读调查可继续；已有会话不被夺取或终止。</p>';options=`<label class="field space-top"><span>方式</span><select id="control-choice"><option value="parallel">并行：各自有可独立交付的范围</option><option value="serial">串行：A1 及有效证据到位，再开始 B 共享实施</option><option value="unified">统一负责人：先请求安全交接，不立即改负责人</option></select></label>`;}
 else{title='收回控制：新动作与已发送动作分开';body='<p class="small sub">停止或撤销不抹去远端已发生的动作。已发请求继续查原回执，已有运行等待安全停止证据；不会自动杀进程或回滚。</p>';options=`<label class="field space-top"><span>具体动作</span><select id="control-choice"><option value="stop-new">停止新实施，不中断现有运行</option><option value="resume-new">恢复新实施，仍检查前置</option><option value="revoke-merge">收回新合并委托，开发和只读检查继续</option><option value="restore-merge">重新允许示例原委托，不扩大范围</option><option value="stop-batch">停止 X1 新增投入，保留已有成果</option><option value="resume-batch">恢复 X1，仍检查采用范围与前置</option></select></label>`;}
 openModal(title,body+options+`<label class="field space-top"><span>本次安排、范围和原因</span><textarea id="control-note">${kind==='boundary'?'采用上述 X1，不增加列明的费用与功能。':kind==='organization'?'按所选方式安排 B 的共享实施；独立调查继续。':'只影响所选的新动作，已发送与未知请求继续核查。'}</textarea></label><div class="notice amber">这是本人操作的离线演练，不是 Agent 替你签字，不修改真实仓库。</div>`,footerHint('确认来源与技术约定分别记录。',btn('确认本次控制','control-confirm',kind,'primary')),'本人入口 / 可恢复决定',false,{kind:'control',action:kind,revision:c.boundary.revision});}
function controlReviewPage(){const c=s.control;return pageHead('REVIEW / LEARN','看判断的后果，不按模型排名。','样本不足就保留未知；表现好不自动扩权。',btn('返回工作秘书','navigate','secretary','ghost'))+`<div class="control-grid"><section class="card pad"><h2>判断与后续结果</h2><p class="small sub space-top">按任务类型、候选、模型／提示版本和暴露时间记录。没有报错不等于正确；需求变化不等于原审核漏检。</p><div class="row wrap space-top">${btn('加入一个漏检演练样本','control-outcome','','sm')}${btn('安排独立抽查','control-sample','','soft sm')}</div>${c.outcomes.length?c.outcomes.map(x=>`<div class="control-entry"><b>${esc(x.taskClass)} · ${esc(x.result)}</b><p>${esc(x.judgment)} @ ${esc(x.candidate)}</p><small>${esc(x.modelVersion)} / ${esc(x.promptVersion)} · ${esc(x.observedAt)}<br>${esc(x.evidence)} · ${esc(x.reason||'尚未归因')}</small></div>`).join(''):'<div class="empty">暂无结果样本。没有“准确率 100%”，没有模型排行榜。</div>'}<div class="notice space-top">${c.outcomes.length} 条演练观察，不支持估计长期准确率；样本结果不会修改委托。</div></section><section class="card pad"><h2>跨 Issue 整体偏移</h2><p class="small sub space-top">对照上一批已接受目标／规则、累计变更、当前行为和当前文档，不只检查“代码与文档一致”。</p>${btn('请求一次整体复盘','control-drift','','soft space-top')}${c.drift.length?c.drift.map(d=>`<div class="control-entry"><b>${esc(d.title)}</b><p>${esc(d.status)}</p><small>对照起点：${esc(d.baseline)}<br>本次范围：X1 及共享接口；当前主干由正式采集确定</small></div>`).join(''):'<div class="empty">没有常驻“架构警察”。一批交付后或重复问题出现时，按范围安排独立检查。</div>'}<details class="source"><summary>文档分三类，不每次都要求你修宪</summary><p>人的边界：目标、风险、费用、权限。团队约定：接口、拆分、检查与合入安排。事实说明：实际入口、当前测试、能力与限制。文档更新本身不批准目标变化。</p></details></section></div>`;}
function controlDecisionPage(){const c=s.control;return pageHead('DECISIONS / AUTHORITY','谁决定的，依据什么，影响哪里。','代理在委托内处置是正常自治；不把“未逐次请示”本身当成违规。',btn('返回秘书','navigate','secretary','ghost'))+`<section class="card pad"><div class="notice">此页只包含演练来源。真实版从本人入口、受限执行身份和原 Issue／PR 引用构建，不因共用 GitHub 账号认定本人批准。</div>${c.decisions.length?c.decisions.map(d=>`<article class="control-entry"><div class="between">${badge(d.origin,d.origin.startsWith('本人')?'green':'purple')}<span class="tiny">${esc(d.at)} · ${esc(d.id)}</span></div><h3 class="space-top">${esc(d.text)}</h3><p class="small sub">依据：${esc(d.authority)}<br>范围：${esc(d.scope||'X1 技术约定')} · 原记录：${esc(d.source||d.id)}</p></article>`).join(''):'<div class="empty">没有新的本人或代理决定。技术记录的出现不会自动产生本人签字。</div>'}</section>`;}
function controlHome(){const c=s.control,ad=c.boundary.state==='adopted';return `<section class="control-hero"><div><div class="up">YOUR PROJECT / YOUR CONTROL</div><h1>你定边界，团队交付。</h1><p>先看本批目标与可用成果；中间技术问题由负责人处理，越界前才找你。</p></div><div class="control-status">${badge(ad?'本批已采用（模拟）':'本批待采用','amber')}${badge((c.stopNew||s.coord.newWorkPaused)?'新实施已停':'新实施按条件推进',(c.stopNew||s.coord.newWorkPaused)?'amber':'green')}</div></section><div class="control-five">${[['本批目标','boundary','做什么、不做什么'],['组织方式','organization','并行、串行、统一负责人'],['委托与停止','limits','收回新动作，保留已发生事实'],['成果验收','delivery','查看实际场景与限制'],['复盘与抽查','review','判断后果与整体偏移']].map(([t,k,d])=>`<button data-action="control-open" data-id="${k}" class="control-tile"><b>${t}</b><small>${d}</small></button>`).join('')}</div><div class="control-grid"><section class="card pad"><div class="between"><h2>${esc(c.boundary.id)} · 本批成果</h2>${badge('目标 v'+c.boundary.revision)}</div><p class="space-top">${esc(c.boundary.goal)}</p><div class="control-adoption space-top"><b>本人采用的边界</b><p>${esc(c.boundary.excluded)}</p><small>${esc(c.boundary.source||'尚未取得本轮采用；团队反馈不能代替。')}</small></div><div class="control-technical"><b>团队可调整的技术约定</b><p>A1 兼容基础 → B1 消费者 → A2 入口。约定变化由负责人核对，超出上方边界才回到你。</p><small>当前组织：${{parallel:'并行',serial:'B 共享实施等待 A1',unified:'统一负责人（待安全交接）'}[c.organization.mode]}</small>${c.organization.mode==='unified'?btn('注入已安全交接证据（模拟）','control-handoff','','ghost sm'):''}</div></section><section class="card pad"><h2>当前需要你的注意力</h2><div class="control-entry"><b>${ad?'边界内继续，无需再批内部子任务':'先采用这一批用户成果'}</b><p class="small sub">普通缺陷、补测试和会话核查默认由技术角色处理，不塞进你的审批箱。</p></div><div class="control-entry"><b>成果状态</b><p class="small sub">${s.coord.delivery?.accepted?'用户场景已登记通过（演练）；正式启用仍独立。':s.coord.delivery?'X1 已进入接入／交付演练；用户场景尚未通过。':'尚未启动 X1 接入演练。先决定目标，再联系相关负责人。'}</p>${btn('打开共同交付','navigate','coordination','sm')}</div><div class="row wrap">${btn('代理处置及其依据','navigate','control-decisions','soft sm')}${btn('直接调整控制','control-open','limits','sm')}${btn('复盘与抽查','navigate','control-review','ghost sm')}</div>${c.lastAction?`<div class="notice space-top">最近已生效的本地安排：${esc(c.lastAction.text)} · ${esc(c.lastAction.id)}</div>`:''}</section></div>`;}
const governanceActions={
 'control-handoff':()=>{if(!controlHandoff('demo/原进程、未提交现场与远端均已核查'))return toast('仍有执行、未知或原操作；不能抢占。先核查原现场。','alert');render();},
 'control-open':k=>k==='review'?navigate('control-review'):k==='delivery'?navigate('coordination'):controlModal(k),
 'control-confirm':k=>{if(modal?.kind!=='control')return;const selected=$('#control-choice').value;const r=controlOwner(k==='organization'?'organization':selected,{mode:selected,revision:modal.revision,note:$('#control-note').value});if(!r.ok)return formError(r.reason);closeModal();render();},
 'control-tech':()=>{if(controlTechnical('保留旧调用兼容，消费者验证后再启用入口；不改变用户目标或预算。'))render();},
 'control-outcome':()=>{controlOutcome({id:'demo-escape-1',candidate:'fixed-demo-tree-1',judgment:'接收 PASS',taskClass:'共享接口／历史消费',modelVersion:'示例模型 v1',promptVersion:'receiver@v2.3',observedAt:'演练观察点 1',result:'escaped',evidence:'fixture/真实消费入口反例（演练）',reason:'同候选的来源归属丢失；需要独立核实归因'});render();},
 'control-sample':()=>{if(!canRecord())return;const id='sample-'+s.control.boundary.revision;if(!s.control.drift.some(x=>x.id===id))s.control.drift.push({id,title:'已放行成果的独立抽样',status:'请求已登记，不代表已检查；覆盖正常放行及已报告异常，说明抽样范围。',baseline:s.control.lastAccepted});event('独立抽查请求','复用新鲜审核上下文，不新增常驻角色');render();},
 'control-drift':()=>{if(!canRecord())return;const id='drift-'+s.control.boundary.revision;if(!s.control.drift.some(x=>x.id===id))s.control.drift.push({id,title:'跨 Issue 整体复盘',status:'请求已登记。缺少上一批基线时明确缺口，不用当前文档替代。',baseline:s.control.lastAccepted});render();}
};
